import { Component } from "@angular/core";
import { RouterOutlet } from "@angular/router";
import { LucideAngularModule } from "lucide-angular";

@Component({
  selector: "app-root",
  standalone: true,
  imports: [RouterOutlet, LucideAngularModule],
  templateUrl: "./app.component.html",
})
export class AppComponent {
  title = "angular-xui";
}

import {
  Component,
  Input,
  Output,
  EventEmitter,
  TemplateRef,
  ChangeDetectionStrategy,
} from "@angular/core";
import { CommonModule } from "@angular/common";
import { buttonVariants } from "./variants";
import { ButtonBaseProps } from "./button.types";

@Component({
  selector: "xui-button",
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: "./button.component.html",
  styleUrls: [],
})
export class ButtonComponent implements ButtonBaseProps {
  @Input() variant: "text" | "contained" | "outlined" = "contained";
  @Input() color:
    | "inherit"
    | "primary"
    | "secondary"
    | "success"
    | "error"
    | "info"
    | "warning" = "primary";
  @Input() size: "small" | "medium" | "large" = "medium";
  @Input() disabled: boolean = false;
  @Input() loading: boolean = false;
  @Input() loadingPosition: "start" | "center" | "end" = "center";
  @Input() fullWidth: boolean = false;
  @Input() disableElevation: boolean = false;
  @Input() component: string = "button";
  @Input() type: "button" | "submit" | "reset" = "button";
  @Input() href?: string;
  @Input() target?: string;
  @Input() role?: string;
  @Input() startIcon?: TemplateRef<unknown>;
  @Input() endIcon?: TemplateRef<unknown>;
  @Input() customLoadingIndicator?: TemplateRef<unknown>;
  @Output() clicked = new EventEmitter<void>();

  get isDisabled(): boolean {
    return this.disabled || this.loading;
  }

  get buttonClasses(): string {
    return buttonVariants({
      variant: this.variant,
      color: this.color,
      size: this.size,
      fullWidth: this.fullWidth,
      disableElevation: this.disableElevation,
    });
  }

  handleClick() {
    if (!this.isDisabled) {
      this.clicked.emit();
    }
  }
}

import {
  Component,
  Input,
  ChangeDetectionStrategy,
  TemplateRef,
} from "@angular/core";
import { CommonModule } from "@angular/common";
import { LinkBaseProps } from "./link.types";
import { LinkVariants } from "./variants";

@Component({
  selector: "app-link",
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: "./link.component.html",
  styleUrls: [],
})
export class LinkComponent implements LinkBaseProps {
  @Input() color:
    | "inherit"
    | "primary"
    | "secondary"
    | "success"
    | "error"
    | "info"
    | "warning" = "primary";
  @Input() className?: string;
  @Input() variant:
    | "inherit"
    | "h1"
    | "h2"
    | "h3"
    | "h4"
    | "h5"
    | "h6"
    | "subtitle1"
    | "subtitle2"
    | "body1"
    | "body2"
    | "body3"
    | "caption" = "inherit";
  @Input() component: string = "a";
  @Input() href?: string;
  @Input() target?: string;
  @Input() rel?: "noopener" | "noreferrer" | undefined;
  @Input() role?: string;
  @Input() underline: "none" | "hover" | "always" = "hover";
  @Input() children?: string | TemplateRef<unknown>;
  //get class of link
  get linkClasses(): string {
    return LinkVariants({
      variant: this.variant,
      color: this.color,
      underline: this.underline,
    });
  }
}

import {
  Component,
  Input,
  Output,
  EventEmitter,
  OnInit,
  OnDestroy,
  OnChanges,
  SimpleChanges,
  TemplateRef,
  NgZone,
} from "@angular/core";
import { DomSanitizer } from "@angular/platform-browser";
import { CommonModule } from "@angular/common";
import {
  trigger,
  state,
  style,
  transition,
  animate,
  AnimationEvent,
} from "@angular/animations";
import { SnackbarAnchorOrigin } from "./snackbar.types";
import { getPositionStyles } from "./variants";
import { SnackbarContentComponent } from "./snackbar-content.component";

@Component({
  selector: "app-snackbar",
  templateUrl: "./snackbar.component.html",
  standalone: true,
  imports: [CommonModule, SnackbarContentComponent],
  animations: [
    // Top-Left
    trigger("slideFromTopLeft", [
      state("void", style({ transform: "translateY(-100%)", opacity: 0 })),
      state("in", style({ transform: "translateY(0)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
    // Top-Center
    trigger("slideFromTopCenter", [
      state("void", style({ transform: "translate(-50%, -100%)", opacity: 0 })),
      state("in", style({ transform: "translateX(-50%)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
    // Top-Right
    trigger("slideFromTopRight", [
      state("void", style({ transform: "translateY(-100%)", opacity: 0 })),
      state("in", style({ transform: "translateY(0)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
    // Bottom-Left
    trigger("slideFromBottomLeft", [
      state("void", style({ transform: "translateY(100%)", opacity: 0 })),
      state("in", style({ transform: "translateY(0)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
    // Bottom-Center
    trigger("slideFromBottomCenter", [
      state("void", style({ transform: "translate(-50%, 100%)", opacity: 0 })),
      state("in", style({ transform: "translateX(-50%)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
    // Bottom-Right
    trigger("slideFromBottomRight", [
      state("void", style({ transform: "translateY(100%)", opacity: 0 })),
      state("in", style({ transform: "translateY(0)", opacity: 1 })),
      transition("void => in", [animate("300ms ease-out")]),
      transition("in => void", [animate("250ms ease-in")]),
    ]),
  ],
})
export class SnackbarComponent implements OnInit, OnDestroy, OnChanges {
  @Input() open: boolean = false;

  @Input() message?: string;
  @Input() action?: TemplateRef<unknown>;
  @Input() autoHideDuration: number = 5000;
  @Input() anchorOrigin: SnackbarAnchorOrigin = {
    vertical: "bottom",
    horizontal: "left",
  };

  @Output() closeHandle = new EventEmitter<void>();

  containerClass: string = "";
  closeButtonClass: string = "";
  autoHideTimeoutId?: number;
  isVisible: boolean = false;
  animationTrigger: string = "";

  constructor(
    private ngZone: NgZone,
    private sanitizer: DomSanitizer,
  ) {}

  ngOnInit(): void {
    this.isVisible = this.open;
    this.updateStyles();
    this.updateAnimation();
    this.setupAutoHide();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["open"] || changes["anchorOrigin"]) {
      if (changes["open"]) {
        this.isVisible = this.open;
      }
      this.updateAnimation();
      this.updateStyles();
      this.setupAutoHide();
    }
  }

  ngOnDestroy(): void {
    this.clearAutoHideTimeout();
  }

  private updateStyles(): void {
    const baseStyles =
      "fixed z-50 flex max-w-md min-w-[356px] items-center rounded-md bg-white text-black";
    const positionStyle = getPositionStyles(this.anchorOrigin);
    this.containerClass = `${baseStyles} ${positionStyle}`;
  }

  private updateAnimation(): void {
    const { vertical, horizontal } = this.anchorOrigin;

    if (vertical === "top") {
      if (horizontal === "left") {
        this.animationTrigger = "slideFromTopLeft";
      } else if (horizontal === "center") {
        this.animationTrigger = "slideFromTopCenter";
      } else {
        this.animationTrigger = "slideFromTopRight";
      }
    } else {
      if (horizontal === "left") {
        this.animationTrigger = "slideFromBottomLeft";
      } else if (horizontal === "center") {
        this.animationTrigger = "slideFromBottomCenter";
      } else {
        this.animationTrigger = "slideFromBottomRight";
      }
    }
  }

  private setupAutoHide(): void {
    this.clearAutoHideTimeout();

    if (this.open && this.autoHideDuration > 0) {
      this.ngZone.runOutsideAngular(() => {
        this.autoHideTimeoutId = window.setTimeout(() => {
          this.ngZone.run(() => {
            this.handleClose();
          });
        }, this.autoHideDuration);
      });
    }
  }

  private clearAutoHideTimeout(): void {
    if (this.autoHideTimeoutId !== undefined) {
      clearTimeout(this.autoHideTimeoutId);
      this.autoHideTimeoutId = undefined;
    }
  }

  handleClose(): void {
    this.clearAutoHideTimeout();
    this.isVisible = false;
  }

  onAnimationDone(event: AnimationEvent): void {
    if (event.toState === "void" && !this.open) {
      this.closeHandle.emit();
    }
  }
}

import { Component, Input, TemplateRef } from "@angular/core";
import { CommonModule } from "@angular/common";

@Component({
  selector: "app-snackbar-content",
  template: `
    <div
      class="m-auto flex min-w-[356px] max-w-lg items-center rounded-md p-4 shadow-lg"
    >
      <div class="flex-grow text-sm font-medium">
        <ng-container *ngIf="message; else contentTpl">{{
          message
        }}</ng-container>
        <ng-template #contentTpl>
          <ng-content></ng-content>
        </ng-template>
      </div>

      <div *ngIf="action" class="ml-auto pl-3">
        <ng-container *ngTemplateOutlet="action"></ng-container>
      </div>
    </div>
  `,
  standalone: true,
  imports: [CommonModule],
})
export class SnackbarContentComponent {
  @Input() message?: string;
  @Input() action?: TemplateRef<unknown>;
}

import { ButtonComponent } from "./button.component";
import { CommonModule } from "@angular/common";
import { Component, TemplateRef, ViewChild } from "@angular/core";

// Helper component to provide template refs for testing
@Component({
  selector: "test-button-host",
  standalone: true,
  imports: [CommonModule, ButtonComponent],
  template: `
    <ng-template #startIconTpl>
      <span data-testid="start-icon">→</span>
    </ng-template>

    <ng-template #endIconTpl>
      <span data-testid="end-icon">←</span>
    </ng-template>

    <ng-template #customLoaderTpl>
      <span data-testid="custom-loader">Loading...</span>
    </ng-template>

    <xui-button
      [variant]="variant"
      [color]="color"
      [size]="size"
      [disabled]="disabled"
      [loading]="loading"
      [loadingPosition]="loadingPosition"
      [fullWidth]="fullWidth"
      [disableElevation]="disableElevation"
      [component]="component"
      [href]="href"
      [target]="target"
      [type]="type"
      [role]="role"
      [startIcon]="startIcon ? startIconTpl : null"
      [endIcon]="endIcon ? endIconTpl : null"
      [customLoadingIndicator]="customLoadingIndicator ? customLoaderTpl : null"
      (clicked)="onClick()"
    >
      {{ content }}
    </xui-button>
  `,
})
class TestButtonHostComponent {
  @ViewChild("startIconTpl") startIconTpl!: TemplateRef<unknown>;
  @ViewChild("endIconTpl") endIconTpl!: TemplateRef<unknown>;
  @ViewChild("customLoaderTpl") customLoaderTpl!: TemplateRef<unknown>;

  variant: "text" | "contained" | "outlined" = "contained";
  color:
    | "inherit"
    | "primary"
    | "secondary"
    | "success"
    | "error"
    | "info"
    | "warning" = "primary";
  size: "small" | "medium" | "large" = "medium";
  disabled: boolean = false;
  loading: boolean = false;
  loadingPosition: "start" | "center" | "end" = "center";
  fullWidth: boolean = false;
  disableElevation: boolean = false;
  component: string = "button";
  href?: string;
  target?: string;
  type: "button" | "submit" | "reset" = "button";
  role?: string;
  content: string = "Button Text";
  startIcon: boolean = false;
  endIcon: boolean = false;
  customLoadingIndicator: boolean = false;

  onClick = cy.stub().as("onClickStub");
}

describe("Button Component", () => {
  it("renders default button correctly", () => {
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        content: "Click me",
      },
    });
    cy.get("button").should("exist").and("contain.text", "Click me");
  });

  it("renders with different variants", () => {
    // Test outlined variant
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        variant: "outlined",
        content: "Outlined",
      },
    });
    cy.get("button").should("have.class", "border");

    // Test text variant with explicitly setting color to inherit
    // to avoid color settings overriding variant styling
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        variant: "text",
        color: "inherit",
        content: "Text Button",
      },
    });
    cy.get("button")
      .should("not.have.class", "bg-primary")
      .and("have.class", "bg-transparent");
  });

  it("renders with different colors", () => {
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        color: "primary",
        content: "Primary",
      },
    });
    cy.get("button").should("exist");

    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        color: "secondary",
        content: "Secondary",
      },
    });
    cy.get("button").should("exist");

    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        color: "error",
        content: "Error",
      },
    });
    cy.get("button").should("exist");
  });

  it("renders with different sizes", () => {
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        size: "small",
        content: "Small",
      },
    });
    cy.get("button").should("have.class", "h-8").and("have.class", "px-3");

    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        size: "large",
        content: "Large",
      },
    });
    cy.get("button").should("have.class", "h-12").and("have.class", "px-6");
  });

  it("renders as a full width button", () => {
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        fullWidth: true,
        content: "Full Width",
      },
    });
    cy.get("button").should("have.class", "w-full");
  });

  it("disables the button when disabled prop is true", () => {
    cy.mount(TestButtonHostComponent, {
      componentProperties: {
        disabled: true,
        content: "Disabled",
      },
    });
    cy.get("button").should("be.disabled");
  });

  it("shows loading state", () => {
