import { SnackbarComponent } from "./snackbar.component";
import { Component } from "@angular/core";
import { CommonModule } from "@angular/common";
import { provideAnimations } from "@angular/platform-browser/animations";

@Component({
  selector: "test-host",
  standalone: true,
  imports: [CommonModule, SnackbarComponent],
  template: `
    <app-snackbar
      [open]="open"
      [message]="message"
      [autoHideDuration]="autoHideDuration"
      [anchorOrigin]="anchorOrigin"
      [withCloseIcon]="withCloseIcon"
      (closeHandle)="handleClose()"
    >
    </app-snackbar>
  `,
})
class TestHostComponent {
  open = true;
  message = "Test message";
  autoHideDuration = 5000;
  anchorOrigin = { vertical: "bottom", horizontal: "left" };

  withCloseIcon = true;

  handleClose() {
    this.open = false;
  }
}

describe("SnackbarComponent", () => {
  const mountComponent = (props = {}) => {
    return cy.mount(TestHostComponent, {
      componentProperties: props,
      providers: [provideAnimations()],
    });
  };

  describe("Basic Rendering", () => {
    it("should render with default props", () => {
      mountComponent();

      cy.get("app-snackbar").should("exist");

      cy.get("app-snackbar")
        .find('div[role="alert"]', { timeout: 5000 })
        .should("be.visible");
      cy.get('app-snackbar div[role="alert"]').should(
        "contain.text",
        "Test message",
      );
    });
  });

  describe("Positioning", () => {
    it("should render at top-right position", () => {
      mountComponent({
        anchorOrigin: { vertical: "top", horizontal: "right" },
      });

      cy.get("app-snackbar")
        .find('div[role="alert"]', { timeout: 5000 })
        .should("be.visible");
    });
  });

  describe("UI Elements", () => {
    it("should render without close icon when withCloseIcon is false", () => {
      mountComponent({ withCloseIcon: false });

      cy.get("app-snackbar button").should("not.exist");
    });
  });

  describe("Content Projection", () => {
    it("should render custom content when no message is provided", () => {
      @Component({
        selector: "test-custom-content-host",
        standalone: true,
        imports: [CommonModule, SnackbarComponent],
        template: `
          <app-snackbar
            [open]="true"
            [autoHideDuration]="5000"
            [withCloseIcon]="true"
          >
            <div data-testid="custom-content">Custom projected content</div>
          </app-snackbar>
        `,
      })
      class TestCustomContentHostComponent {}

      cy.mount(TestCustomContentHostComponent, {
        providers: [provideAnimations()],
      });

      cy.get("app-snackbar")
        .find('[data-testid="custom-content"]', { timeout: 5000 })
        .should("be.visible");
      cy.get('[data-testid="custom-content"]').should(
        "contain.text",
        "Custom projected content",
      );
    });
  });
});

import { LinkComponent } from "./link.component";
import { CommonModule } from "@angular/common";
import { Component } from "@angular/core";

@Component({
  selector: "test-link-host",
  standalone: true,
  imports: [CommonModule, LinkComponent],
  template: `
    <app-link
      [className]="className"
      [variant]="variant"
      [color]="color"
      [underline]="underline"
      [component]="component"
      [href]="href"
      [target]="target"
      [role]="role"
    >
      {{ content }}
    </app-link>
  `,
})
class TestLinkHostComponent {
  variant:
    | "inherit"
    | "h1"
    | "h2"
    | "h3"
    | "h4"
    | "h5"
    | "h6"
    | "subtitle1"
    | "subtitle2"
    | "body1"
    | "body2"
    | "caption" = "inherit";
  underline: "none" | "hover" | "always" = "hover";
  color:
    | "inherit"
    | "primary"
    | "secondary"
    | "success"
    | "error"
    | "info"
    | "warning" = "primary";
  href: string = "#";
  target: string = "_self";
  role?: string;
  content: string = "Link";
  className: string = "link-class";
  component: string = "a"; // Default to anchor tag
}

describe("Link Component", () => {
  it("renders default link correctly", () => {
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        content: "Default Link",
      },
    });
    cy.get("a")
      .should("exist")
      .and("have.attr", "href", "#")
      .and("contain.text", "Default Link");
  });
  // Test with text decoration class
  it("renders with different text decorations", () => {
    // Test always underline
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        underline: "always",
      },
    });
    cy.get("a").should("have.class", "underline");
    // Test hover underline

    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        underline: "hover",
      },
    });
    cy.get("a").should("have.class", "hover:underline");
    // Test non underline

    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        underline: "none",
      },
    });
    cy.get("a").should("have.class", "no-underline");
  });
  // Test color of link
  it("renders with different colors", () => {
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        color: "inherit",
      },
    });
    cy.get("a").should("exist");

    //primary color
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        color: "primary",
      },
    });
    cy.get("a").should("exist");

    //secondary color
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        color: "secondary",
      },
    });
    cy.get("a").should("exist");
    //warning color
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        color: "warning",
      },
    });
    cy.get("a").should("exist");
  });
  //test render as custom component
  it("renders as a custom component", () => {
    cy.mount(TestLinkHostComponent, {
      componentProperties: {
        component: "button",
        role: "button",
        content: "Link",
      },
    });
    cy.get("a")
      .should("exist")
      .and("not.have.attr", "href", "#")
      .and("have.attr", "role", "button")
      .and("contain.text", "Link");
  });
});

import { Component, Input } from "@angular/core";
import { CommonModule } from "@angular/common";

@Component({
  selector: "app-typography",
  standalone: true,
  imports: [CommonModule],
  template: `
    <div [class]="classes">
      {{ text }}
    </div>
  `,
})
export class TypographyComponent {
  @Input() variant:
    | "h1"
    | "h2"
    | "h3"
    | "h4"
    | "subtitle1"
    | "subtitle2"
    | "body1"
    | "body2"
    | "caption" = "body1";
  @Input() text: string = "";

  get classes(): string {
    const variantClasses = {
      h1: "text-5xl font-bold text-gray-900 leading-tight",
      h2: "text-4xl font-semibold text-gray-900 leading-tight",
      h3: "text-3xl font-semibold text-gray-900 leading-snug",
      h4: "text-2xl font-medium text-gray-900 leading-snug",
      subtitle1: "text-xl font-medium text-gray-800 leading-relaxed",
      subtitle2: "text-lg font-medium text-gray-800 leading-relaxed",
      body1: "text-base text-gray-700 leading-relaxed",
      body2: "text-sm text-gray-700 leading-relaxed",
      caption: "text-xs text-gray-600 leading-normal",
    };

    return variantClasses[this.variant];
  }
}

